add_action( 'woocommerce_order_status_changed', 'perfectpixel_send_email_on_status_change', 20, 4 );

function perfectpixel_send_email_on_status_change( $order_id, $from, $to, $order ) {
	foreach ( explode( '|', '{{status_email_rules}}' ) as $rule ) {
		if ( ! preg_match( '/^\s*([a-z0-9_*-]+)\s*>\s*([a-z0-9_-]+)\s*=\s*([a-z0-9_]+)\s*$/', $rule, $m ) ) {
			continue;
		}
		if ( ( '*' !== $m[1] && $m[1] !== $from ) || $m[2] !== $to ) {
			continue;
		}
		foreach ( WC()->mailer()->get_emails() as $email ) {
			if ( $email->id === $m[3] && $email->is_enabled() ) {
				$email->trigger( $order_id, $order );
			}
		}
	}
}
